"""Task-local inspection: list workspace files and describe any SQLite databases."""
import os
import sqlite3

print("Current directory:", os.getcwd())
print("Files:")
for name in sorted(os.listdir(".")):
    print(" -", name, os.path.getsize(name) if os.path.isfile(name) else "(dir)")

print("\nSQLite databases:")
for name in sorted(os.listdir(".")):
    if name.endswith(".db") or name.endswith(".sqlite") or name.endswith(".sqlite3"):
        print(f"  {name}:")
        try:
            with sqlite3.connect(name) as conn:
                rows = conn.execute(
                    "SELECT name, type FROM sqlite_master "
                    "WHERE type IN ('table', 'index') ORDER BY name"
                ).fetchall()
                if not rows:
                    print("    (no tables)")
                for table, kind in rows:
                    print(f"    {kind}: {table}")
                # Show schema of each table
                for table, kind in rows:
                    if kind == "table":
                        schema = conn.execute(
                            "SELECT sql FROM sqlite_master WHERE name = ?", (table,)
                        ).fetchone()
                        print(f"    schema {table}: {schema[0] if schema else 'n/a'}")
        except sqlite3.Error as exc:
            print("    error:", exc)

